"""Offline payload compilation, client replay and origin evidence audit."""
import json
import gc
import keyword
import math
import re
import sys
from pathlib import Path

# The local no-Docker worker stages the same pinned wheels here. In the public
# image the packages are installed normally and this directory is unnecessary.
if Path('/opt/h3deps').is_dir():
    sys.path.insert(0,'/opt/h3deps')

from schema import compile_cases
from modules.byte_program import Context, MAX
from modules.fuzz_adapter import FuzzExecutor
from modules.capture_audit import audit_channels, TOKEN

NAME = re.compile(r'[A-Za-z0-9_.-]{1,32}\Z',re.ASCII)
SEED = re.compile(r'[A-Za-z0-9_.-]{0,64}\Z',re.ASCII)
DEFINITION_NAME = re.compile(r'[A-Za-z][A-Za-z0-9_]{0,31}\Z',re.ASCII)

MAX_DEFINITIONS = 8192
MAX_CASES = 2000
MAX_CHANNELS = 256
MAX_BUDGET = 50000
MAX_HEADER_PAIRS = 32768
MAX_BLOCK_PAIRS = 128
MAX_EXPRESSION = 8192
MAX_TEMPLATE = 65536
MAX_TIMEOUT = 10 ** 9


def exact(obj,keys):
    if type(obj) is not dict or set(obj)!=set(keys):
        raise ValueError('object keys')


def allowed(obj,keys,required):
    if type(obj) is not dict:
        raise ValueError('object')
    if not set(obj).issubset(keys):
        raise ValueError('object keys')
    for key in required:
        if key not in obj:
            raise ValueError('missing key')


def integer(value,minimum=0,maximum=MAX):
    if type(value) is not int or not minimum <= value <= maximum:
        raise ValueError('integer')
    return value


def sequence(value,maximum):
    if type(value) is not list or len(value)>maximum:
        raise ValueError('array')
    return value


def text(value,maximum=MAX_TEMPLATE):
    if type(value) is not str or len(value)>maximum:
        raise ValueError('string')
    value.encode('utf8')
    return value


def visible(value,maximum=8192):
    text(value,maximum)
    try:
        encoded = value.encode('ascii')
    except UnicodeEncodeError:
        raise ValueError('ascii')
    if not encoded or len(encoded)>maximum:
        raise ValueError('length')
    for byte in encoded:
        if byte < 33 or byte > 126:
            raise ValueError('visible')
    return encoded


def bad_constant(value):
    raise ValueError('nonfinite JSON')


def finite_float(value):
    result = float(value)
    if not math.isfinite(result):
        raise ValueError('nonfinite JSON')
    return result


def validate_frame(frame,pairs):
    """Validate one fuzz frame and count its header pairs."""
    if type(frame) is not dict:
        raise ValueError('frame')
    kind = frame.get('Type')
    if type(kind) is not str:
        raise ValueError('frame type')
    if kind == 'headers':
        allowed(frame,{'Type','headers_kv','data_to_transfered','End_Stream'},{'Type'})
        has_map = 'headers_kv' in frame
        has_list = 'data_to_transfered' in frame
        if has_map == has_list:
            raise ValueError('header source')
        if has_map:
            value = frame['headers_kv']
            if type(value) is not dict:
                raise ValueError('header mapping')
            if len(value)>MAX_BLOCK_PAIRS:
                raise ValueError('header pairs')
            for name,item in value.items():
                text(name)
                text(item)
            pairs[0] += len(value)
        else:
            value = frame['data_to_transfered']
            if type(value) is not list or len(value)>MAX_BLOCK_PAIRS:
                raise ValueError('header pairs')
            for pair in value:
                if type(pair) is not list or len(pair)!=2:
                    raise ValueError('header pair')
                text(pair[0])
                text(pair[1])
            pairs[0] += len(value)
        if 'End_Stream' in frame and type(frame['End_Stream']) is not bool:
            raise ValueError('End_Stream')
        return
    if kind in ('data','datagram'):
        allowed(frame,{'Type','data_to_transfered','End_Stream'},{'Type','data_to_transfered'})
        text(frame['data_to_transfered'])
        if 'End_Stream' in frame and type(frame['End_Stream']) is not bool:
            raise ValueError('End_Stream')
        return
    if kind == 'sleep':
        exact(frame,['Type','Time_to_Stop'])
        integer(frame['Time_to_Stop'])
        return
    raise ValueError('frame type')


def compile_document(document):
    """Validate the whole document and compile every template."""
    exact(document,['seed','definitions','timeout_ms','cases','events','channels'])
    seed = text(document['seed'],64)
    if SEED.fullmatch(seed) is None:
        raise ValueError('seed')
    definitions = sequence(document['definitions'],MAX_DEFINITIONS)
    sources = []
    for row in definitions:
        if type(row) is not list or len(row)!=2:
            raise ValueError('definition pair')
        name = text(row[0],32)
        if DEFINITION_NAME.fullmatch(name) is None or keyword.iskeyword(name):
            raise ValueError('definition name')
        sources.append((name,text(row[1],MAX_EXPRESSION)))
    context = Context(sources,seed)
    timeout = integer(document['timeout_ms'],1,MAX_TIMEOUT)

    cases = sequence(document['cases'],MAX_CASES)
    names = set()
    budget = 0
    pairs = [0]
    validated = []
    for case in cases:
        exact(case,['name','frames','expect'])
        name = text(case['name'],32)
        if NAME.fullmatch(name) is None or name in names:
            raise ValueError('case name')
        names.add(name)
        frames = sequence(case['frames'],MAX_BUDGET)
        budget += len(frames)
        pause_total = 0
        for frame in frames:
            validate_frame(frame,pairs)
            if frame['Type']=='sleep':
                pause_total += frame['Time_to_Stop']
        if pause_total+timeout>MAX:
            raise ValueError('time overflow')
        expect = case['expect']
        exact(expect,['method','target','host'])
        visible(expect['method'])
        visible(expect['target'])
        visible(expect['host'])
        if TOKEN.fullmatch(expect['method'].encode('ascii')) is None:
            raise ValueError('expected method')
        validated.append({'name':name,'frames':frames,'expect':expect})

    payload = compile_cases(validated)

    records = sequence(document['events'],MAX_BUDGET)
    budget += len(records)
    events = []
    for index,record in enumerate(records):
        if type(record) is not dict:
            raise ValueError('event')
        kind = record.get('kind')
        if kind=='close':
            exact(record,['at','kind'])
        elif kind=='headers':
            exact(record,['at','kind','stream','end','fields'])
        elif kind=='data':
            exact(record,['at','kind','stream','end','data'])
        else:
            raise ValueError('event kind')
        integer(record['at'])
        row = {'at':record['at'],'kind':kind}
        if kind!='close':
            integer(record['stream'],0,(1<<32)-1)
            if type(record['end']) is not bool:
                raise ValueError('event end')
            row['stream'] = record['stream']
            row['end'] = record['end']
        if kind=='headers':
            raw_fields = record['fields']
            if type(raw_fields) is not list or len(raw_fields)>MAX_BLOCK_PAIRS:
                raise ValueError('event fields')
            pairs[0] += len(raw_fields)
            fields = []
            for j,pair in enumerate(raw_fields):
                if type(pair) is not list or len(pair)!=2:
                    raise ValueError('event pair')
                fields.append((context.template(text(pair[0]),'event/%d/h/%d/n'%(index,j)),
                               context.template(text(pair[1]),'event/%d/h/%d/v'%(index,j))))
            row['fields'] = fields
        elif kind=='data':
            row['data'] = context.template(text(record['data']),'event/%d/data'%index)
        events.append(row)

    channels = sequence(document['channels'],MAX_CHANNELS)
    channel_names = set()
    compiled_channels = []
    for index,channel in enumerate(channels):
        exact(channel,['name','parts'])
        name = text(channel['name'],32)
        if NAME.fullmatch(name) is None or name in channel_names:
            raise ValueError('channel name')
        channel_names.add(name)
        parts = sequence(channel['parts'],MAX_BUDGET)
        budget += len(parts)
        out_parts = []
        for j,part in enumerate(parts):
            exact(part,['case','data'])
            owner = part['case']
            if owner is not None and (type(owner) is not str or owner not in names):
                raise ValueError('owner label')
            out_parts.append({'case':owner,
                              'data':context.template(text(part['data']),
                                                       'channel/%d/part/%d/data'%(index,j))})
        compiled_channels.append({'name':name,'parts':out_parts})

    if budget>MAX_BUDGET or pairs[0]>MAX_HEADER_PAIRS:
        raise ValueError('combined budget')
    return validated,payload,events,compiled_channels,timeout,context


def run(document):
    cases,payload,events,channels,timeout,context = compile_document(document)
    fuzzer = FuzzExecutor(context)
    sent = fuzzer.send_payload(payload.test_cases,events,timeout)
    origin,evidence = audit_channels(channels,cases,sent)
    for record in sent:
        info = evidence.get(record['name'])
        count = info['origin_count'] if info else 0
        flags = set()
        if record['request_frames']>0 and count==0:
            flags.add('missing_origin')
        if count>1:
            flags.add('extra_origin')
        if count>0 and record['request_frames']==0:
            flags.add('unsent_origin')
        if info is not None and info['identity']:
            flags.add('identity')
        if info is not None and info['mixed']:
            flags.add('mixed_origin')
        record['origin_count'] = count
        record['flags'] = sorted(flags)
    return {'cases':sent,'channels':origin}


def main():
    gc.disable()
    try:
        raw = sys.stdin.buffer.read(8*1024**2+1)
        if len(raw)>8*1024**2:
            raise ValueError('input bytes')
        document = json.loads(raw.decode('utf8'),object_pairs_hook=lambda items: _unique(items),
                              parse_constant=bad_constant,parse_float=finite_float)
        result = run(document)
    except (ValueError,TypeError,KeyError,IndexError,UnicodeError,RecursionError,OverflowError):
        result = {'error':'input'}
    encoded = json.dumps(result,ensure_ascii=True,separators=(',',':'),allow_nan=False).encode('ascii')
    sys.stdout.buffer.write(encoded+b'\n')


def _unique(items):
    out = {}
    for key,value in items:
        if key in out:
            raise ValueError('duplicate key')
        out[key] = value
    return out


if __name__=='__main__':main()
